// Auto-generated from the Video Outreach Playbook doc. Rendered natively in PlaybookView.
export const PLAYBOOK_CSS = ".pbdoc{\n  --navy:#003D7A; --navy2:#004A94; --deep:#002A55; --ink:#242A2E;\n  --blue:#0066CC; --blue2:#4DA3FF; --bluesoft:#E7F0FB; --blueline:#C2DAF2;\n  --amber:#003D7A; --ambersoft:#EAF2FB; --amberline:#CFE1F4;\n  --paper:#F4F7FB; --card:#FFFFFF; --border:#E2E9F1; --muted:#5C6670; --muted2:#8A929C;\n}\n.pbdoc *{box-sizing:border-box;-webkit-tap-highlight-color:transparent;}\n.pbdoc{margin:0;font-family:'Inter',-apple-system,system-ui,sans-serif;background:var(--paper);\n  color:var(--ink);font-size:17px;line-height:1.62;-webkit-text-size-adjust:100%;}\n.pbdoc .wrap{max-width:680px;margin:0 auto;}\n.pbdoc h1, .pbdoc h2, .pbdoc h3, .pbdoc h4{font-family:'Inter',sans-serif;color:var(--navy);margin:0;line-height:1.18;letter-spacing:-0.01em;}\n.pbdoc p{margin:0 0 13px;}\n.pbdoc b, .pbdoc strong{font-weight:650;color:var(--ink);}\n.pbdoc a{color:var(--blue);text-decoration:none;}\n.pbdoc em{font-style:italic;}\n.pbdoc ul{margin:6px 0 14px;padding:0;list-style:none;}\n.pbdoc li{position:relative;padding-left:22px;margin:0 0 9px;}\n.pbdoc li::before{content:\"\";position:absolute;left:3px;top:10px;width:6px;height:6px;border-radius:50%;background:var(--blue);}\n.pbdoc .topbar{position:sticky;top:0;z-index:50;background:rgba(255,255,255,.94);backdrop-filter:blur(8px);\n  display:flex;align-items:center;justify-content:space-between;padding:12px 18px;\n  border-bottom:1px solid var(--border);}\n.pbdoc .topbar .bx{display:flex;align-items:center;gap:9px;}\n.pbdoc .topbar .nm{font-family:'Inter';font-weight:600;color:#122F52;font-size:15px;letter-spacing:.01em;}\n.pbdoc .topbar .nm .lt{font-weight:300;color:#0066CC;}\n.pbdoc .topbar a.toc{font-family:'Inter';font-weight:600;font-size:13px;color:#0066CC;\n  border:1px solid var(--blueline);padding:6px 13px;border-radius:20px;}\n.pbdoc .mark-blue, .pbdoc .mark-white{display:inline-flex;align-items:center;}\n.pbdoc .mark-white{display:none;}\n.pbdoc[data-theme=\"dark\"] .mark-blue{display:none;}\n.pbdoc[data-theme=\"dark\"] .mark-white{display:inline-flex;}\n.pbdoc[data-theme=\"dark\"] .topbar{background:rgba(0,42,85,.97);border-bottom-color:rgba(120,160,215,.22);}\n.pbdoc[data-theme=\"dark\"] .topbar .nm{color:#EAF1FF;}\n.pbdoc[data-theme=\"dark\"] .topbar .nm .lt{color:#8FBEEF;}\n.pbdoc[data-theme=\"dark\"] .topbar a.toc{color:#9CC0FF;border-color:rgba(120,160,215,.42);}\n.pbdoc .hero{background:linear-gradient(180deg,#E7F1FC 0%,#F2F7FD 55%,#FFFFFF 100%);\n  color:#122F52;padding:40px 22px 34px;border-bottom:1px solid var(--border);}\n.pbdoc .hero .eyebrow{font-family:'Inter';font-weight:600;font-size:12px;letter-spacing:.2em;\n  text-transform:uppercase;color:#0066CC;margin-bottom:14px;}\n.pbdoc .hero h1{color:#0B2A4A;font-size:34px;font-weight:700;line-height:1.05;letter-spacing:-0.015em;}\n.pbdoc .hero h1 .b{color:#0066CC;}\n.pbdoc .hero .bar{width:54px;height:3px;background:#0066CC;border-radius:3px;margin:20px 0 16px;}\n.pbdoc .hero p{color:#4C5B6E;font-size:16px;margin:0;}\n.pbdoc .hero .meta{margin-top:20px;display:flex;gap:10px;flex-wrap:wrap;}\n.pbdoc .hero .pill{font-family:'Inter';font-weight:600;font-size:11px;letter-spacing:.08em;text-transform:uppercase;\n  color:#0066CC;border:1px solid var(--blueline);border-radius:20px;padding:5px 12px;background:rgba(255,255,255,.6);}\n.pbdoc[data-theme=\"dark\"] .hero{background:radial-gradient(130% 100% at 80% 0%,#0A5BAF 0%,#003D7A 46%,#00234A 100%);\n  color:#fff;border-bottom:none;}\n.pbdoc[data-theme=\"dark\"] .hero .eyebrow{color:#4DA3FF;}\n.pbdoc[data-theme=\"dark\"] .hero h1{color:#fff;}\n.pbdoc[data-theme=\"dark\"] .hero h1 .b{color:#4DA3FF;}\n.pbdoc[data-theme=\"dark\"] .hero .bar{background:#4DA3FF;}\n.pbdoc[data-theme=\"dark\"] .hero p{color:#B9C7DC;}\n.pbdoc[data-theme=\"dark\"] .hero .pill{color:#9CC0FF;border-color:rgba(120,160,215,.4);background:transparent;}\n.pbdoc .pad{padding:0 22px;}\n.pbdoc .toc{background:var(--card);border:1px solid var(--border);border-radius:16px;padding:8px 6px;margin:22px 0 6px;}\n.pbdoc .toc a{display:flex;align-items:center;gap:14px;padding:12px 14px;border-bottom:1px solid var(--border);}\n.pbdoc .toc a:last-child{border-bottom:none;}\n.pbdoc .toc .n{font-family:'Inter';font-weight:700;color:var(--blue);font-size:15px;width:26px;flex:none;}\n.pbdoc .toc .t{font-family:'Inter';font-weight:600;color:var(--navy);font-size:16px;line-height:1.2;}\n.pbdoc .toc .s{font-size:13px;color:var(--muted);margin-top:1px;}\n.pbdoc section{padding:34px 22px 10px;scroll-margin-top:64px;}\n.pbdoc section + section{border-top:10px solid #EAF0F8;}\n.pbdoc .kick{display:inline-flex;align-items:center;gap:9px;font-family:'Inter';font-weight:600;font-size:12px;\n  letter-spacing:.15em;text-transform:uppercase;color:var(--blue);margin-bottom:11px;}\n.pbdoc .kick .num{font-family:'Inter';font-weight:700;color:var(--navy);}\n.pbdoc .kick::before{content:\"\";width:22px;height:2px;background:var(--blue);border-radius:2px;}\n.pbdoc section > h2{font-size:26px;font-weight:600;margin-bottom:10px;}\n.pbdoc .sub{color:var(--muted);font-size:16px;margin-bottom:20px;}\n.pbdoc h3.blk{font-size:19px;font-weight:600;margin:22px 0 9px;}\n.pbdoc h4.mini{font-family:'Inter';font-weight:600;font-size:16px;color:var(--navy);margin:16px 0 5px;}\n.pbdoc .card{background:var(--card);border:1px solid var(--border);border-radius:15px;padding:17px 18px;margin:0 0 14px;}\n.pbdoc .card h4{font-family:'Inter';font-weight:600;font-size:17px;color:var(--navy);margin:0 0 6px;}\n.pbdoc .card p{margin:0;font-size:15.5px;color:var(--ink);}\n.pbdoc .card ul{margin:8px 0 0;}\n.pbdoc .card li{font-size:15.5px;}\n.pbdoc .eyebrow{font-family:'Inter';font-weight:600;font-size:12px;letter-spacing:.12em;text-transform:uppercase;\n  color:var(--blue);margin-bottom:8px;}\n.pbdoc .tint{background:var(--bluesoft);border:1px solid var(--blueline);border-radius:15px;padding:17px 18px;margin:0 0 14px;}\n.pbdoc .tint p{margin:0;font-size:15.5px;}\n.pbdoc .soft{background:#F0F4FA;border:1px solid var(--border);border-radius:15px;padding:17px 18px;margin:0 0 14px;}\n.pbdoc .tip{background:var(--ambersoft);border:1px solid var(--amberline);border-radius:15px;padding:16px 18px;margin:0 0 14px;}\n.pbdoc .tip .lbl{font-family:'Inter';font-weight:700;font-size:12px;letter-spacing:.1em;text-transform:uppercase;\n  color:var(--amber);margin-bottom:5px;}\n.pbdoc .tip p{margin:0;font-size:15.5px;}\n.pbdoc .big{font-family:'Inter';font-weight:500;font-size:18px;color:var(--navy);line-height:1.4;margin:0;}\n.pbdoc .stats{display:flex;gap:11px;margin:4px 0 16px;}\n.pbdoc .stats .s{flex:1;background:var(--card);border:1px solid var(--border);border-radius:14px;padding:15px 8px;text-align:center;}\n.pbdoc .stats .v{font-family:'Inter';font-weight:700;font-size:26px;color:var(--blue);line-height:1;}\n.pbdoc .stats .l{font-size:12px;color:var(--muted);margin-top:6px;line-height:1.3;}\n.pbdoc .script{background:var(--card);border:1px solid var(--border);border-left:4px solid var(--blue);\n  border-radius:13px;padding:15px 17px;margin:0 0 13px;}\n.pbdoc .script .chip{display:inline-block;background:var(--navy);color:#fff;font-family:'Inter';font-weight:600;\n  font-size:12.5px;letter-spacing:.02em;padding:4px 12px;border-radius:20px;margin-bottom:9px;}\n.pbdoc .script .when{font-size:14px;color:var(--muted);margin-bottom:9px;}\n.pbdoc .script .when b{color:var(--navy);}\n.pbdoc .script .say{font-size:15.5px;line-height:1.55;}\n.pbdoc .script .say em{color:var(--blue);font-style:normal;font-weight:600;}\n.pbdoc .step{display:flex;gap:13px;margin:0 0 14px;}\n.pbdoc .step .n{flex:none;width:32px;height:32px;border-radius:9px;background:var(--navy);color:#fff;\n  font-family:'Inter';font-weight:600;font-size:16px;display:flex;align-items:center;justify-content:center;}\n.pbdoc .step .n.blue{background:var(--blue);}\n.pbdoc .step .t{font-family:'Inter';font-weight:600;font-size:16.5px;color:var(--navy);margin-bottom:2px;}\n.pbdoc .step p{margin:0;font-size:15px;color:var(--muted);}\n.pbdoc .drow{background:var(--card);border:1px solid var(--border);border-radius:13px;padding:14px 16px;margin:0 0 11px;}\n.pbdoc .drow .top{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:4px;}\n.pbdoc .drow .nm{font-family:'Inter';font-weight:600;font-size:16px;color:var(--navy);}\n.pbdoc .drow .wt{font-family:'Inter';font-weight:700;font-size:15px;color:var(--blue);flex:none;}\n.pbdoc .drow .wt.neg{color:#C0392B;}\n.pbdoc .drow p{margin:0;font-size:14.5px;color:var(--muted);}\n.pbdoc .badge{display:inline-block;font-family:'Inter';font-weight:600;font-size:12px;letter-spacing:.03em;\n  padding:3px 10px;border-radius:20px;background:var(--bluesoft);color:var(--blue);border:1px solid var(--blueline);}\n.pbdoc .badge.navy{background:var(--navy);color:#fff;border-color:var(--navy);}\n.pbdoc .chk{display:flex;align-items:flex-start;gap:12px;padding:11px 0;border-bottom:1px dashed #D6DFEA;}\n.pbdoc .chk .box{flex:none;width:20px;height:20px;border:2px solid var(--blue);border-radius:5px;margin-top:1px;}\n.pbdoc .chk .tx{font-size:15.5px;}\n.pbdoc .chk .tx b{color:var(--navy);}\n.pbdoc .grouplbl{font-family:'Inter';font-weight:600;font-size:12px;letter-spacing:.12em;text-transform:uppercase;\n  color:var(--blue);margin:18px 0 4px;}\n.pbdoc .phase{background:var(--card);border:1px solid var(--border);border-left:4px solid var(--blue);\n  border-radius:14px;padding:16px 18px;margin:0 0 14px;}\n.pbdoc .phase .ph{display:flex;align-items:center;gap:10px;margin-bottom:8px;}\n.pbdoc .phase .lab{font-family:'Inter';font-weight:600;font-size:12px;letter-spacing:.04em;text-transform:uppercase;\n  background:var(--navy);color:#fff;padding:4px 11px;border-radius:20px;}\n.pbdoc .phase h4{font-family:'Inter';font-weight:600;font-size:17px;color:var(--navy);margin:0;}\n.pbdoc .phase .g{color:var(--muted);font-size:14.5px;margin:0 0 8px;}\n.pbdoc .phase li{font-size:15px;margin-bottom:6px;}\n.pbdoc .beat{display:flex;gap:12px;align-items:flex-start;background:var(--card);border:1px solid var(--border);\n  border-radius:13px;padding:13px 15px;margin:0 0 10px;}\n.pbdoc .beat .tm{flex:none;}\n.pbdoc .beat h4{font-size:16px;margin:6px 0 2px;}\n.pbdoc .beat p{margin:0;font-size:14.5px;color:var(--muted);}\n.pbdoc .foot{background:var(--deep);color:#8DA1C0;text-align:center;padding:30px 22px 34px;margin-top:20px;}\n.pbdoc .foot .big{color:#EAF1FF;font-family:'Inter';font-weight:500;font-size:17px;line-height:1.45;max-width:520px;margin:0 auto 16px;}\n.pbdoc .foot .sm{font-size:12px;letter-spacing:.1em;text-transform:uppercase;color:#6E84A4;font-family:'Inter';}\n.pbdoc .totop{display:inline-block;margin-top:14px;font-family:'Inter';font-weight:600;font-size:13px;color:#9CC0FF;\n  border:1px solid rgba(120,150,200,.4);padding:8px 16px;border-radius:20px;}\n.pbdoc .two{display:grid;grid-template-columns:1fr;gap:0;}\n.pbdoc .tbtn{display:inline-flex;align-items:center;justify-content:center;width:36px;height:33px;\n  border:1px solid rgba(120,150,200,.4);border-radius:20px;background:transparent;cursor:pointer;\n  font-size:15px;line-height:1;padding:0;margin-right:9px;}\n.pbdoc .topbar .right{display:flex;align-items:center;}\n.pbdoc .chk{cursor:pointer;user-select:none;-webkit-user-select:none;}\n.pbdoc .chk .box{transition:background .12s,border-color .12s;position:relative;}\n.pbdoc .chk.on .box{background:var(--blue);border-color:var(--blue);}\n.pbdoc .chk.on .box::after{content:\"\";position:absolute;left:5px;top:1px;width:5px;height:10px;\n  border:solid #fff;border-width:0 2.5px 2.5px 0;transform:rotate(45deg);}\n.pbdoc .chk.on .tx{color:var(--muted2);text-decoration:line-through;text-decoration-color:rgba(130,146,166,.55);}\n.pbdoc .chk.on .tx b{color:var(--muted2);}\n.pbdoc .chkbar{display:flex;justify-content:flex-end;margin-bottom:6px;}\n.pbdoc .chkbar button{font-family:'Inter';font-weight:600;font-size:13px;color:var(--blue);background:transparent;\n  border:1px solid var(--blueline);border-radius:20px;padding:7px 15px;cursor:pointer;}\n.pbdoc[data-theme=\"dark\"]{\n  --paper:#071726; --card:#0E2338; --ink:#DCE6F2; --muted:#9DB0C6; --muted2:#7C8DA4;\n  --border:#22405A; --navy:#0B4A87; --blue:#4DA3FF; --bluesoft:rgba(0,102,204,.18); --blueline:rgba(77,163,255,.34);\n  --amber:#4DA3FF; --ambersoft:rgba(0,102,204,.16); --amberline:rgba(77,163,255,.34);\n}\n.pbdoc[data-theme=\"dark\"] h1, .pbdoc[data-theme=\"dark\"] h2, .pbdoc[data-theme=\"dark\"] h3, .pbdoc[data-theme=\"dark\"] h4, .pbdoc[data-theme=\"dark\"] .toc .t, .pbdoc[data-theme=\"dark\"] .kick .num, .pbdoc[data-theme=\"dark\"] .card h4, .pbdoc[data-theme=\"dark\"] h4.mini, .pbdoc[data-theme=\"dark\"] .big, .pbdoc[data-theme=\"dark\"] .script .when b, .pbdoc[data-theme=\"dark\"] .step .t, .pbdoc[data-theme=\"dark\"] .drow .nm, .pbdoc[data-theme=\"dark\"] .chk .tx b, .pbdoc[data-theme=\"dark\"] .phase h4{color:#F0F5FC;}\n.pbdoc[data-theme=\"dark\"] .soft{background:#0F2942;}\n.pbdoc[data-theme=\"dark\"] section + section{border-top-color:#0E2135;}\n.pbdoc[data-theme=\"dark\"] .chk{border-bottom-color:#284563;}\n.pbdoc[data-theme=\"dark\"] .drow .wt.neg{color:#FF6B5A;}\n.pbdoc[data-theme=\"dark\"] .tbtn, .pbdoc[data-theme=\"dark\"] .topbar a.toc{border-color:rgba(120,160,215,.36);}";

export const PLAYBOOK_HTML = "<div class=\"wrap\">\n<div id=\"contents\" style=\"scroll-margin-top:64px;padding-top:26px;\" class=\"pad\">\n  <div class=\"kick\">&nbsp;Contents</div><h2 style=\"font-family:'Grotesk';font-size:24px;\">What's inside</h2>\n</div>\n<div class=\"pad\"><div class=\"toc\"><a href=\"#why\"><span class=\"n\">01</span><span><span class=\"t\">The psychology of video outreach</span><div class=\"s\">Why a 60-second video beats a cold call</div></span></a><a href=\"#icp\"><span class=\"n\">02</span><span><span class=\"t\">Your ideal prospect</span><div class=\"s\">The trades that convert and how to spot them</div></span></a><a href=\"#prospecting\"><span class=\"n\">03</span><span><span class=\"t\">Finding the best prospects daily</span><div class=\"s\">Sources, signals, and the lead scorecard</div></span></a><a href=\"#system\"><span class=\"n\">04</span><span><span class=\"t\">The daily outreach system</span><div class=\"s\">A time-blocked operating rhythm</div></span></a><a href=\"#setup\"><span class=\"n\">05</span><span><span class=\"t\">Recording setup</span><div class=\"s\">Camera, mic, lighting, and software</div></span></a><a href=\"#workflow\"><span class=\"n\">06</span><span><span class=\"t\">The Loom recording workflow</span><div class=\"s\">Eight steps from research to send</div></span></a><a href=\"#anatomy\"><span class=\"n\">07</span><span><span class=\"t\">Anatomy of a winning video</span><div class=\"s\">The 60-second structure that books calls</div></span></a><a href=\"#scripts\"><span class=\"n\">08</span><span><span class=\"t\">The script library</span><div class=\"s\">19 openers for every situation</div></span></a><a href=\"#channels\"><span class=\"n\">09</span><span><span class=\"t\">Channel templates</span><div class=\"s\">Email, Messenger, Instagram, and SMS</div></span></a><a href=\"#followup\"><span class=\"n\">10</span><span><span class=\"t\">The 30-day follow-up sequence</span><div class=\"s\">Persistence without being a pest</div></span></a><a href=\"#objections\"><span class=\"n\">11</span><span><span class=\"t\">Objection handling</span><div class=\"s\">Answers to the eight you'll hear most</div></span></a><a href=\"#metrics\"><span class=\"n\">12</span><span><span class=\"t\">Metrics & CRM tracking</span><div class=\"s\">The numbers that predict revenue</div></span></a><a href=\"#casestudy\"><span class=\"n\">13</span><span><span class=\"t\">The case study template</span><div class=\"s\">Turn wins into proof</div></span></a><a href=\"#plan\"><span class=\"n\">14</span><span><span class=\"t\">The 90-day outreach plan</span><div class=\"s\">Daily goals across three phases</div></span></a><a href=\"#checklist\"><span class=\"n\">15</span><span><span class=\"t\">The daily checklist</span><div class=\"s\">Print it. Run it. Every day.</div></span></a><a href=\"#pricing\"><span class=\"n\">16</span><span><span class=\"t\">Offer & pricing reference</span><div class=\"s\">The numbers to quote with confidence</div></span></a></div></div>\n<section id=\"why\">\n      <div class=\"kick\"><span class=\"num\">Section 01</span>&nbsp;The why</div>\n      <h2>The psychology of video outreach</h2><p class=\"sub\">Why a 60-second video beats a cold call</p>\n<div class=\"stats\">\n  <div class=\"s\"><div class=\"v\">8×</div><div class=\"l\">higher reply rates vs. cold email</div></div>\n  <div class=\"s\"><div class=\"v\">3s</div><div class=\"l\">to show a face, name & their business</div></div>\n  <div class=\"s\"><div class=\"v\">0</div><div class=\"l\">interruptions — they watch on their time</div></div>\n</div>\n<h4 class=\"mini\">It collapses the trust gap</h4>\n<p>A cold caller is a stranger reading a script. A video shows a real person who already looked at <em>their</em> website and named a real problem. Effort reads as competence — before you've claimed a single skill.</p>\n<h4 class=\"mini\">It's asynchronous</h4>\n<p>The contractor is on a roof or under a sink all day. A video waits in their inbox until 8pm when they finally sit down. You never interrupt; you just show up prepared.</p>\n<h4 class=\"mini\">It demonstrates, not describes</h4>\n<p>Instead of saying \"your site is hard to use,\" you share your screen and <em>show</em> the quote button that doesn't work on a phone. Seeing the leak is what creates the urgency to fix it.</p>\n<div class=\"tint\">\n  <div class=\"eyebrow\">The mechanism</div>\n  <p style=\"margin-bottom:7px;\"><b>Reciprocity.</b> You gave free, specific insight — people give attention back.</p>\n  <p style=\"margin-bottom:7px;\"><b>Specificity.</b> \"I noticed X on your site\" can only be true if you actually looked — and they know it.</p>\n  <p><b>Low ask.</b> You request a watch, not a meeting. The micro-yes makes the next yes easier.</p>\n</div>\n<div class=\"tip\"><div class=\"lbl\">Pro tip</div><p>Cold calls fail because they ask for time before earning it. Video flips the order: <b>earn the trust first, ask for the call second.</b></p></div>\n<div class=\"soft\"><div class=\"eyebrow\">The one-line philosophy</div>\n  <p class=\"big\">Don't pitch a product. Hand them a free diagnosis of a problem they didn't know they had — then be the obvious person to fix it.</p></div>\n</section><section id=\"icp\">\n      <div class=\"kick\"><span class=\"num\">Section 02</span>&nbsp;Who you sell to</div>\n      <h2>Your ideal prospect</h2><p class=\"sub\">The trades that convert and how to spot them</p>\n<div class=\"card\"><h4>Painters</h4><p style=\"margin-bottom:6px;\">Project-based, referral-heavy, weak web presence</p><p style=\"font-size:14px;color:var(--blue);font-weight:600;\">Fit: High — your home turf; instant credibility from 15 years painting</p></div><div class=\"card\"><h4>HVAC</h4><p style=\"margin-bottom:6px;\">Emergency + seasonal demand, missed calls = lost jobs</p><p style=\"font-size:14px;color:var(--blue);font-weight:600;\">Fit: Very high — missed-call text-back is a perfect fit</p></div><div class=\"card\"><h4>Roofers</h4><p style=\"margin-bottom:6px;\">High ticket, storm-driven urgency, ad spend leaking</p><p style=\"font-size:14px;color:var(--blue);font-weight:600;\">Fit: High — they feel every lost lead in dollars</p></div><div class=\"card\"><h4>Plumbers</h4><p style=\"margin-bottom:6px;\">Urgent calls, often solo or small crews, no after-hours capture</p><p style=\"font-size:14px;color:var(--blue);font-weight:600;\">Fit: Very high — after-hours capture is a clear win</p></div><div class=\"card\"><h4>Electricians</h4><p style=\"margin-bottom:6px;\">Steady demand, weak booking flow, slow to reply</p><p style=\"font-size:14px;color:var(--blue);font-weight:600;\">Fit: Medium-high — booking + follow-up automation</p></div><div class=\"card\"><h4>Landscaping / lawn</h4><p style=\"margin-bottom:6px;\">Seasonal, lots of quote requests, poor follow-up</p><p style=\"font-size:14px;color:var(--blue);font-weight:600;\">Fit: Medium — quote follow-up automation lands well</p></div>\n<div class=\"soft\"><div class=\"eyebrow\">Green lights — prioritize</div>\n<ul style=\"margin:0;\"><li>Owner answers the phone (decisions happen fast)</li><li>5–25 reviews and clearly wants more work</li><li>Runs Google or Facebook ads (values leads)</li><li>DIY site on Wix / GoDaddy that's plateaued</li><li>No mobile-friendly booking or quote form</li></ul></div>\n<div class=\"soft\"><div class=\"eyebrow\">Red flags — skip or deprioritize</div>\n<ul style=\"margin:0;\"><li>National franchise (decisions aren't local)</li><li>Zero web presence <em>and</em> zero interest in growing</li><li>Already has a marketing agency on retainer</li><li>Hostile or unreachable — no owner contact</li><li>Brand-new, no reviews, no budget signal</li></ul></div>\n<div class=\"tip\"><div class=\"lbl\">Your unfair advantage</div><p>You've been painting for 15 years and grew up in the trades. With painters especially, lead with that — \"I've run a brush for 15 years myself\" disarms the \"you don't understand my world\" objection before it's spoken.</p></div>\n</section><section id=\"prospecting\">\n      <div class=\"kick\"><span class=\"num\">Section 03</span>&nbsp;Prospecting</div>\n      <h2>Finding the best prospects daily</h2><p class=\"sub\">Sources, signals, and the lead scorecard</p>\n<h3 class=\"blk\">Where to find them</h3>\n<div class=\"card\"><h4>Google Maps / Local Pack</h4><p>Search \"[trade] + [town]\" across your county. Businesses ranking 4–15 are gold: real demand, not dominating. Note reviews, photos, and whether the site link even works.</p></div>\n<div class=\"card\"><h4>Google Business Profile gaps</h4><p>Unclaimed profiles, no website link, no hours, few photos, unanswered reviews. Each gap is a talking point you can show on camera.</p></div>\n<div class=\"card\"><h4>Facebook & community groups</h4><p>Local \"recommend a [trade]\" threads reveal who's active but under-marketed. Owners posting their own work often have no real website behind them.</p></div>\n<div class=\"card\"><h4>Running ads = budget signal</h4><p>See a local contractor's ad (check the Facebook Ad Library)? They already pay for leads — and are almost certainly leaking some. Top of your list.</p></div>\n<h3 class=\"blk\">The 5-point qualification scan</h3>\n<p class=\"sub\" style=\"margin-bottom:14px;\">90 seconds per prospect. Score each yes as a point.</p>\n<div class=\"card\"><span class=\"badge\">1 · Demand</span><p style=\"margin-top:8px;\">Reviews, photos, ads — is anyone trying to grow here?</p></div>\n<div class=\"card\"><span class=\"badge\">2 · Visible leak</span><p style=\"margin-top:8px;\">Can you point to one concrete problem on screen in 20 seconds?</p></div>\n<div class=\"card\"><span class=\"badge\">3 · Reachability</span><p style=\"margin-top:8px;\">Is there an email, DM, or form to actually deliver the video?</p></div>\n<div class=\"card\"><span class=\"badge\">4 · Owner-led</span><p style=\"margin-top:8px;\">Small enough that the owner decides — not a committee.</p></div>\n<div class=\"card\"><span class=\"badge\">5 · Means</span><p style=\"margin-top:8px;\">Established enough to afford a setup + monthly without flinching.</p></div>\n<p><b>4–5 = record today.</b> 3 = backup list. 0–2 = skip and move on.</p>\n<h3 class=\"blk\">The lead scorecard</h3>\n<p class=\"sub\" style=\"margin-bottom:14px;\">Run every prospect through the same filter, then record top-down.</p>\n<div class=\"drow\"><div class=\"top\"><span class=\"nm\">Visible problem</span><span class=\"wt\">+3</span></div><p>A leak you can show on screen: broken mobile form, no booking, dead site</p></div><div class=\"drow\"><div class=\"top\"><span class=\"nm\">Spends on ads</span><span class=\"wt\">+3</span></div><p>Active Google/Facebook ads — proven willingness to pay for leads</p></div><div class=\"drow\"><div class=\"top\"><span class=\"nm\">Growth intent</span><span class=\"wt\">+2</span></div><p>Recent reviews, fresh photos, \"now hiring,\" or job posts</p></div><div class=\"drow\"><div class=\"top\"><span class=\"nm\">Owner-operated</span><span class=\"wt\">+2</span></div><p>Owner's name/face on the site or profile; small team</p></div><div class=\"drow\"><div class=\"top\"><span class=\"nm\">Reachable</span><span class=\"wt\">+1</span></div><p>Email, working contact form, or active social DMs</p></div><div class=\"drow\"><div class=\"top\"><span class=\"nm\">In your trades</span><span class=\"wt\">+1</span></div><p>Painting, HVAC, roofing, plumbing — where your story lands</p></div><div class=\"drow\"><div class=\"top\"><span class=\"nm\">No way to reach</span><span class=\"wt neg\">−2</span></div><p>Phone only, no email/DM/form — can't deliver the video</p></div><div class=\"drow\"><div class=\"top\"><span class=\"nm\">Has an agency</span><span class=\"wt neg\">−3</span></div><p>Footer credits a marketing firm; already locked up</p></div>\n<div class=\"tint\"><div class=\"eyebrow\">How to read the score</div>\n<p style=\"margin-bottom:5px;\"><b>8+ &nbsp;Record today.</b> Strong fit, clear leak, can pay.</p>\n<p style=\"margin-bottom:5px;\"><b>5–7 &nbsp;Warm.</b> Record if you have quota left.</p>\n<p><b>&lt;5 &nbsp;Park it.</b> Revisit only on a slow day.</p></div>\n<div class=\"tip\"><div class=\"lbl\">Pro tip</div><p>Build the list <b>the afternoon before</b>, not the morning of. Walking into your recording block with 12 pre-scored prospects is the biggest lever on your daily output.</p></div>\n</section><section id=\"system\">\n      <div class=\"kick\"><span class=\"num\">Section 04</span>&nbsp;The system</div>\n      <h2>The daily outreach system</h2><p class=\"sub\">A time-blocked operating rhythm</p>\n<div class=\"step\"><div class=\"n blue\">A</div><div><div class=\"t\">Prep block — 20 min</div><p>Pull yesterday's pre-scored list. Open each prospect's site + Google profile. Jot one leak per prospect. Never research and record in the same breath.</p></div></div><div class=\"step\"><div class=\"n blue\">B</div><div><div class=\"t\">Recording block — 60–75 min</div><p>Record 8–10 videos back to back. One take each, same energy. Don't edit, don't rewatch — momentum is everything.</p></div></div><div class=\"step\"><div class=\"n blue\">C</div><div><div class=\"t\">Send & log block — 20 min</div><p>Deliver via the best channel. Log each with date, channel, and the leak you flagged. No log = no follow-up = wasted video.</p></div></div><div class=\"step\"><div class=\"n blue\">D</div><div><div class=\"t\">Follow-up block — 20 min</div><p>Work the queue: anyone at day 3, 7, 14, or 30. This block quietly produces most of your booked calls.</p></div></div><div class=\"step\"><div class=\"n blue\">E</div><div><div class=\"t\">Reply & book block — as needed</div><p>Replies are the priority interrupt. Answer fast, drop your booking link, confirm a time.</p></div></div>\n<div class=\"tint\"><div class=\"eyebrow\">The daily number</div>\n<p><b>10 personalized videos per weekday.</b> That's 50 a week, ~200 a month. That volume is what turns this from a hobby into a pipeline. Miss a day? Don't double up — just don't miss two.</p></div>\n</section><section id=\"setup\">\n      <div class=\"kick\"><span class=\"num\">Section 05</span>&nbsp;Setup</div>\n      <h2>Recording setup</h2><p class=\"sub\">Camera, mic, lighting, and software</p>\n<div class=\"card\"><h4>🎥 Camera</h4><p>Laptop webcam is fine to start; a 1080p USB webcam at eye level reads as more intentional.</p>\n<ul><li>Lens at eye height — stack books under the laptop</li><li>Frame head-and-shoulders with a little headroom</li><li>Look at the <em>lens</em>, not your face on screen</li></ul></div>\n<div class=\"card\"><h4>🎙️ Microphone</h4><p>The biggest quality jump for the least money. Wired earbuds beat a laptop mic; a USB or lav mic is better still.</p>\n<ul><li>Record in a soft room — rugs, not bathrooms</li><li>Mic within ~12 inches of your mouth</li><li>Kill background noise: fans, AC, the dog</li></ul></div>\n<div class=\"card\"><h4>💡 Lighting</h4><p>Face a window. Natural daylight in front of you flatters more than any ring light behind you.</p>\n<ul><li>Never sit with a window <em>behind</em> you</li><li>Soft, even light — avoid harsh overhead shadows</li></ul></div>\n<div class=\"card\"><h4>🧱 Background</h4><p>Tidy and on-brand beats blurred and busy. A clean wall or a branded element signals \"real business.\"</p></div>\n<div class=\"tip\"><div class=\"lbl\">The 80/20 of looking pro</div><p><b>Fix your audio and face a window.</b> Those two moves beat any camera upgrade. Test a 10-second clip on your phone before recording for real.</p></div>\n<h3 class=\"blk\">Software & screen recording</h3>\n<p>The whole pitch hinges on one move: <b>your face in the corner while you walk through their website.</b> Loom is built for exactly that.</p>\n<div class=\"card\"><h4>Why Loom is the default</h4>\n<ul style=\"margin-top:4px;\"><li>Cam bubble + screen in one click</li><li>Instant shareable link when you stop</li><li>View notifications — you know when they watch (a buying signal)</li><li>Built-in CTA button → your booking link</li></ul></div>\n<div class=\"soft\"><div class=\"eyebrow\">One-time Loom setup</div>\n<ul style=\"margin:0;\"><li>Install desktop app + browser extension</li><li>Default to Screen + Cam, bubble bottom-left</li><li>Set the right mic (your USB/lav, not the webcam)</li><li>Add a default CTA → your Cal.com link</li><li>Turn on view + comment notifications</li></ul></div>\n<div class=\"card\"><div class=\"eyebrow\">Delivery & tracking stack</div><p>Loom (record) → email / DM / SMS (deliver) → <b>Cal.com</b> (book) → your tracker/CRM (log + follow up). Owned end-to-end — same no-lock-in philosophy you sell clients.</p></div>\n</section><section id=\"workflow\">\n      <div class=\"kick\"><span class=\"num\">Section 06</span>&nbsp;Execution</div>\n      <h2>The Loom recording workflow</h2><p class=\"sub\">Eight steps from research to send</p>\n<div class=\"step\"><div class=\"n\">1</div><div><div class=\"t\">Open their world</div><p>Their website + Google profile in tabs. Glance at your note: which one leak are you showing?</p></div></div><div class=\"step\"><div class=\"n\">2</div><div><div class=\"t\">Set the frame</div><p>Screen + cam, bubble bottom-left, correct mic. Smile before you hit record — it carries into your voice.</p></div></div><div class=\"step\"><div class=\"n\">3</div><div><div class=\"t\">Hook with their name</div><p>First 5 seconds: say the business name and that you were just on their site.</p></div></div><div class=\"step\"><div class=\"n\">4</div><div><div class=\"t\">Show the leak</div><p>Share screen, point at the one problem. Try the broken mobile button live. Let them <em>see</em> it.</p></div></div><div class=\"step\"><div class=\"n\">5</div><div><div class=\"t\">Bridge to the fix</div><p>One or two sentences on how your managed system closes that gap.</p></div></div><div class=\"step\"><div class=\"n\">6</div><div><div class=\"t\">Soft CTA</div><p>Invite, don't pressure: \"Want me to send the demo?\" or \"Worth a 20-minute call?\"</p></div></div><div class=\"step\"><div class=\"n\">7</div><div><div class=\"t\">Stop. Don't rewatch.</div><p>One take. Stutters read as human and unscripted — that's a feature.</p></div></div><div class=\"step\"><div class=\"n\">8</div><div><div class=\"t\">Title, deliver, log</div><p>Title it \"Quick idea for [Business] 👋\", send it, log the prospect. Next.</p></div></div>\n<div class=\"tip\"><div class=\"lbl\">Keep it to 60 seconds</div><p>Aim for <b>45–75 seconds.</b> Specific enough to matter, short enough that a busy owner finishes it. Over 90 seconds means you're explaining too much — save it for the call.</p></div>\n</section><section id=\"anatomy\">\n      <div class=\"kick\"><span class=\"num\">Section 07</span>&nbsp;Structure</div>\n      <h2>Anatomy of a winning video</h2><p class=\"sub\">The 60-second structure that books calls</p>\n<div class=\"beat\"><span class=\"badge tm\">0–10s</span><div><h4>Hook</h4><p>Their business name + \"I was just on your site.\" Earn the next 50 seconds.</p></div></div><div class=\"beat\"><span class=\"badge tm\">10–30s</span><div><h4>Observation</h4><p>Show the one leak on screen. Concrete, visible, costing them jobs.</p></div></div><div class=\"beat\"><span class=\"badge tm\">30–50s</span><div><h4>Solution</h4><p>Your managed system closes the gap. Outcome first, mechanics second.</p></div></div><div class=\"beat\"><span class=\"badge tm\">50–60s</span><div><h4>Invite</h4><p>Point them to your How It Works demo, or grab 20 minutes.</p></div></div>\n<div class=\"soft\"><div class=\"eyebrow\">Do</div><ul style=\"margin:0;\"><li>Name <em>one</em> problem — clarity beats a list</li><li>Lead with their outcome (more booked jobs), not your tech</li><li>Speak like a tradesperson, not a marketer</li><li>End with a single, easy ask</li></ul></div>\n<div class=\"soft\"><div class=\"eyebrow\">Don't</div><ul style=\"margin:0;\"><li>List five issues — it reads as a teardown</li><li>Say \"Zapier,\" \"API,\" \"Cloudflare\" — jargon loses them</li><li>Pitch price on video — that's a call conversation</li><li>Beg for the meeting — invite, stay relaxed</li></ul></div>\n<div class=\"tint\"><div class=\"eyebrow\">The frame to hold</div><p class=\"big\">You're a peer in the trades who noticed they're leaving money on the table — and you happen to fix exactly that. Helpful neighbor, not vendor.</p></div>\n<h3 class=\"blk\">The demo = your How It Works page</h3>\n<p class=\"sub\" style=\"margin-bottom:12px;\">One link, nothing to record.</p>\n<p>The personalized Loom's only job is to <em>hook</em> them. When a script says \"watch the demo,\" you send the link to your <b>How It Works page</b> — the interactive walkthrough that does the selling for you. Nothing to record, and it's always up to date.</p>\n<div class=\"soft\"><div class=\"eyebrow\">What the page walks through</div>\n<ul style=\"margin:0;\"><li>A real quote-form submission, start to finish</li><li>The missed-call text-back firing (mocked live)</li><li>The automatic follow-up &amp; booking that follows</li><li>Prospects can click through it at their own pace</li></ul></div>\n<div class=\"tip\"><div class=\"lbl\">How to use it</div><p>Drop the <em>same</em> How It Works link into every Loom follow-up, email, DM, and SMS. In the video, just say \"I'll send a link that shows exactly how it works.\"</p></div>\n<div class=\"soft\"><div class=\"eyebrow\">Why a page beats a video</div><p style=\"margin:0;\">Always current, interactive, and self-paced — they explore it instead of just watching.</p></div>\n</section><section id=\"scripts\">\n      <div class=\"kick\"><span class=\"num\">Section 08</span>&nbsp;The script library</div>\n      <h2>The script library</h2><p class=\"sub\">19 openers for every situation</p><div class=\"script\"><span class=\"chip\">No website</span><div class=\"when\"><b>When to use:</b> Contractor has reviews and demand but no site at all.</div><div class=\"say\">Hi — this is Alignment Automations. I was looking for [Business] online and noticed there's no website yet, which means anyone searching for you after hours has nowhere to request a quote. I build and fully manage the whole thing — site, hosting, instant missed-call text-back, and automatic follow-up — so leads don't slip past you. <em>I put together a quick demo of exactly how it works — want me to send it over?</em></div></div><div class=\"script\"><span class=\"chip\">Outdated website</span><div class=\"when\"><b>When to use:</b> Site exists but looks dated and converts poorly.</div><div class=\"say\">Hey, I just pulled up [Business]'s website and the work looks great — but the site itself is doing you a disservice. A few small changes would turn more visitors into quote requests. I handle the website, hosting, follow-up, and maintenance so you never touch the tech. <em>I recorded a 60-second walkthrough of what I'd change — worth a look?</em></div></div><div class=\"script\"><span class=\"chip\">Not mobile-friendly</span><div class=\"when\"><b>When to use:</b> Site is broken or clunky on a phone (most of their traffic).</div><div class=\"say\">Quick one for [Business]: I opened your site on my phone — like most of your customers do — and the quote button is almost impossible to tap. You're probably losing leads and never knowing it. I rebuild it mobile-first and add automatic follow-up so nothing leaks. <em>Want to see the side-by-side?</em></div></div><div class=\"script\"><span class=\"chip\">Slow site</span><div class=\"when\"><b>When to use:</b> Page takes several seconds to load.</div><div class=\"say\">Hi [Business] — I was on your website and it took about six seconds to load. Most people bail before three. That's lost jobs you never even see. I host on fast infrastructure and add missed-call text-back so the leads you do get actually convert. <em>I'll send a short demo if you're curious.</em></div></div><div class=\"script\"><span class=\"chip\">No Google Business Profile / unclaimed</span><div class=\"when\"><b>When to use:</b> Profile is missing, unclaimed, or barely filled out.</div><div class=\"say\">Quick heads-up for [Business]: your Google Business Profile is missing hours and photos, and that's usually the first place local customers look before they ever reach your site. I'll hand you a step-by-step guide to claim and fix it up yourself in about an hour, alongside the new site, so the two work together instead of one being empty. <em>Mind if I send a 60-second demo of the rest?</em></div></div><div class=\"script\"><span class=\"chip\">Few or no reviews</span><div class=\"when\"><b>When to use:</b> Clearly does good work but has under ~10 reviews.</div><div class=\"say\">Hi [Business] — your work looks solid, but you've only got a handful of Google reviews, and that's costing you jobs against competitors with fifty. That gap usually comes down to missed calls and quote requests that never get followed up on — jobs that would've become another five-star review just slip away first. I fix that capture-and-follow-up gap so more of what you're already getting turns into finished work. <em>Want to see how it works?</em></div></div><div class=\"script\"><span class=\"chip\">Missed-call leak</span><div class=\"when\"><b>When to use:</b> Solo or small crew that obviously can't catch every call.</div><div class=\"say\">Hey — this is Alignment Automations. As a [trade], you're on the job all day and can't grab every call — and a missed call from a homeowner usually means they dial the next guy. I set up instant missed-call text-back: the second you miss a call, they get a text and you keep the lead. <em>I'll send a quick demo — it's the easiest win there is.</em></div></div><div class=\"script\"><span class=\"chip\">No after-hours capture</span><div class=\"when\"><b>When to use:</b> Phone-only business with no way to catch evening/weekend leads.</div><div class=\"say\">Hi [Business] — homeowners do most of their searching at night and on weekends, exactly when nobody's answering the phone. Right now those leads just vanish. I add 24/7 capture: missed-call text-back plus an online quote request, so after-hours turns into booked work instead of lost calls. <em>Want the 60-second version?</em></div></div><div class=\"script\"><span class=\"chip\">No online booking</span><div class=\"when\"><b>When to use:</b> Customers can only book by playing phone tag.</div><div class=\"say\">Hey — this is Alignment Automations. To book [Business] right now, a customer has to call, leave a message, and wait for a call back. Half of them won't. I add simple online scheduling tied to your calendar, so they pick a slot in 20 seconds and you both skip the phone tag. <em>I'll show you how clean it looks if you want.</em></div></div><div class=\"script\"><span class=\"chip\">Bad / missing contact form</span><div class=\"when\"><b>When to use:</b> Form is buried, broken, or asks for too much.</div><div class=\"say\">Quick one for [Business]: your contact form asks for nine fields and half of them aren't needed — people start it and give up. I replace it with a two-tap quote request that fires an instant text to you and an auto-reply to them, so leads get answered in seconds. <em>Worth seeing the before-and-after?</em></div></div><div class=\"script\"><span class=\"chip\">DIY site plateau (Wix/GoDaddy)</span><div class=\"when\"><b>When to use:</b> Owner built it themselves and it's stopped working for them.</div><div class=\"say\">Hey [Business] — looks like you built the site yourself, which is honestly more than most owners do. But it's hit a ceiling on turning visitors into actual quote requests. I take it off your plate entirely and add the automation behind it, so you get the leads without the late-night website wrestling. <em>Want a quick walkthrough?</em></div></div><div class=\"script\"><span class=\"chip\">Great site, no automation</span><div class=\"when\"><b>When to use:</b> Polished website but nothing happens after a lead comes in.</div><div class=\"say\">Your website actually looks great — nice work. The one thing I didn't see was any automatic follow-up when someone calls and misses you or fills out the form. That's where leads quietly die. I add the automation behind the scenes — text-back, follow-up, reminders — so more of the leads you're already getting turn into jobs. <em>Want to see what that layer looks like?</em></div></div><div class=\"script\"><span class=\"chip\">Spending on ads, leaking leads</span><div class=\"when\"><b>When to use:</b> Running Google/Facebook ads but capture is weak.</div><div class=\"say\">Hey [Business] — I noticed you're running ads, which means you're paying for every click. But the landing experience and follow-up aren't catching those leads, so you're losing a chunk of what you paid for. I tighten the capture and add instant follow-up so your ad dollars actually convert. <em>I'll send a short demo — this one usually pays for itself fast.</em></div></div><div class=\"script\"><span class=\"chip\">Seasonal slowdown</span><div class=\"when\"><b>When to use:</b> Trade with a clear off-season (HVAC, landscaping, painting).</div><div class=\"say\">Hi [Business] — heading into your slower stretch, the leads you do get matter even more, and missing even one hurts. I set up a system that captures and follows up on every single inquiry automatically, so a quieter season doesn't mean a leaky one. <em>Want me to show you how it keeps the pipeline warm?</em></div></div><div class=\"script\"><span class=\"chip\">Newly licensed / new business</span><div class=\"when\"><b>When to use:</b> Just got licensed or recently opened — building from zero.</div><div class=\"say\">Hey — congrats on getting [Business] off the ground. I run a painting business too, so I know the early grind. The fastest way to look established and stop losing those first leads is a clean site plus automatic follow-up from day one. I build and manage all of it so you can stay on the tools. <em>Want a quick look at what I'd set up?</em></div></div><div class=\"script\"><span class=\"chip\">Referral-only, wants to scale</span><div class=\"when\"><b>When to use:</b> Word-of-mouth business ready to grow beyond referrals.</div><div class=\"say\">Hey [Business] — looks like you've built a great referral business, which is the hard part. The next level is catching the people who find you online and search at 9pm, and right now there's no net for them. I add the site and automation that turn that traffic into booked jobs. <em>Want to see how it bolts onto what you've already got?</em></div></div><div class=\"script\"><span class=\"chip\">Competitor comparison</span><div class=\"when\"><b>When to use:</b> A clearly better-marketed competitor is winning locally.</div><div class=\"say\">Hi [Business] — I was comparing a few [trade]s in [city], and the ones pulling ahead online aren't doing better work, they just capture and follow up on leads better. That gap is fixable fast. I set you up with the same kind of system so you stop losing jobs to slicker marketing. <em>Want me to show you the difference?</em></div></div><div class=\"script\"><span class=\"chip\">Re-engagement (gone quiet)</span><div class=\"when\"><b>When to use:</b> Prospect you contacted before who never replied.</div><div class=\"say\">Hey [Business] — circling back because I still think there's an easy win here. Since I last reached out, [new detail / they got busier]. The offer's the same: I handle the website and automatic follow-up so leads stop slipping. <em>If now's better timing, I'll resend the demo — just say the word.</em></div></div><div class=\"script\"><span class=\"chip\">The bundle close</span><div class=\"when\"><b>When to use:</b> Strong-fit prospect ready for the full system.</div><div class=\"say\">Hi [Business] — based on what I'm seeing, you'd get the most from the full Intake System: a fast, mobile-first website plus the missed-call text-back and follow-up that captures every lead behind it. I run the whole thing for you, you own all of it, and there's no lock-in. <em>Worth 20 minutes to map out exactly what it'd look like for you?</em></div></div><div class=\"tip\"><div class=\"lbl\">Make any script yours</div><p>Swap one detail you could only know by looking — a specific page, their service area, a recent review. That proof-of-effort line is what separates a real video from a template.</p></div></section><section id=\"channels\">\n      <div class=\"kick\"><span class=\"num\">Section 09</span>&nbsp;Delivery</div>\n      <h2>Channel templates</h2><p class=\"sub\">Email, Messenger, Instagram, and SMS</p>\n<div class=\"card\"><div class=\"eyebrow\">Email</div>\n<p style=\"margin-bottom:4px;\"><b>Subject:</b> Quick idea for [Business] 👋</p>\n<p style=\"margin-bottom:10px;font-size:14px;color:var(--muted);\"><b>Alt:</b> Noticed something on your site</p>\n<p style=\"font-size:15px;\">Hi [Name],<br><br>I recorded a quick 60-second video showing one opportunity I spotted on [Business]'s website — no sales pitch, just a couple of ideas to help you catch more leads.<br><br>👉 [Loom link]<br><br>If it looks useful, I'd be glad to show you how my fully managed system handles the website and follow-up for you.<br><br>— Alignment Automations</p></div>\n<div class=\"card\"><div class=\"eyebrow\">Facebook Messenger</div>\n<p style=\"font-size:15px;\">Hey [Name]! 👋 I came across [Business] and made a quick 60-sec video about one thing on your site that could be quietly costing you leads. No pitch — just thought it'd be useful 👉 [link]</p>\n<p style=\"font-size:14px;color:var(--muted);margin-top:8px;\"><b>If they reply:</b> \"Glad it helped! Want a short demo of how I'd set it up, or easier to grab 20 min this week?\"</p></div>\n<div class=\"card\"><div class=\"eyebrow\">Instagram DM</div>\n<p style=\"font-size:14px;color:var(--muted);margin-bottom:8px;\">Warm up first — like or comment on a recent job photo, then DM a day later.</p>\n<p style=\"font-size:15px;\">Hey! Love the work on your feed 🔥 I made you a quick 60-sec video about one thing on your website that could be losing you quote requests — no pitch. Cool if I drop the link here?</p></div>\n<div class=\"card\"><div class=\"eyebrow\">SMS <span style=\"font-weight:400;text-transform:none;letter-spacing:0;color:var(--muted);\">— only with a legit business number</span></div>\n<p style=\"font-size:15px;\">Hi [Name] — Alignment Automations here. Made a quick 60-sec video on one fix that could get [Business] more quote requests. No pitch: [link]</p></div>\n<div class=\"tip\"><div class=\"lbl\">Channel etiquette</div><p>Match each channel's norms — email fuller, DMs casual, SMS most personal (reserve it for warmer prospects). One message, one link, zero pressure.</p></div>\n</section><section id=\"followup\">\n      <div class=\"kick\"><span class=\"num\">Section 10</span>&nbsp;Persistence</div>\n      <h2>The 30-day follow-up sequence</h2><p class=\"sub\">Persistence without being a pest</p>\n<div class=\"drow\"><div class=\"top\"><span class=\"nm\">Day 0</span><span class=\"badge\">Video</span></div><p style=\"color:var(--ink);\"><b>The original.</b> Personalized 60-sec video + short note.</p></div><div class=\"drow\"><div class=\"top\"><span class=\"nm\">Day 3</span><span class=\"badge\">Same channel</span></div><p style=\"color:var(--ink);\"><b>Gentle bump.</b> \"Just making sure the video came through — no worries if now's not the time.\"</p></div><div class=\"drow\"><div class=\"top\"><span class=\"nm\">Day 7</span><span class=\"badge\">Same / email</span></div><p style=\"color:var(--ink);\"><b>Add value.</b> \"Curious what you thought — here's a 2-min example of it working for a similar [trade].\"</p></div><div class=\"drow\"><div class=\"top\"><span class=\"nm\">Day 14</span><span class=\"badge\">Email / call</span></div><p style=\"color:var(--ink);\"><b>New angle.</b> Reframe around a different leak. \"Different thought — here's where the bigger win actually is.\"</p></div><div class=\"drow\"><div class=\"top\"><span class=\"nm\">Day 21</span><span class=\"badge\">Email</span></div><p style=\"color:var(--ink);\"><b>Soft proof.</b> Drop a short case study or testimonial. Low ask.</p></div><div class=\"drow\"><div class=\"top\"><span class=\"nm\">Day 30</span><span class=\"badge\">Email / DM</span></div><p style=\"color:var(--ink);\"><b>Close the loop.</b> \"I'll stop reaching out after this — but if catching more leads is ever on your list, I'm one message away.\"</p></div>\n<div class=\"tint\"><div class=\"eyebrow\">Rules of the sequence</div><ul style=\"margin:0;\"><li>Every touch adds something — never just \"bumping this\"</li><li>Stop the instant they reply or book</li><li>Never guilt-trip; the day-30 close stays warm</li></ul></div>\n<div class=\"tip\"><div class=\"lbl\">Pro tip</div><p>Loom tells you when they watched. A view with no reply isn't a no — it's a warm lead. Prioritize watchers in your follow-up block.</p></div>\n</section><section id=\"objections\">\n      <div class=\"kick\"><span class=\"num\">Section 11</span>&nbsp;Objections</div>\n      <h2>Objection handling</h2><p class=\"sub\">Answers to the eight you'll hear most</p>\n<div class=\"card\"><h4 style=\"color:var(--blue);\">“We're too busy right now”</h4><p style=\"margin-top:5px;font-size:15.5px;\">That's the point — the system runs in the background so you don't have to think about it. And busy season is exactly when missed calls cost the most. Want me to handle the setup so you don't lift a finger?</p></div><div class=\"card\"><h4 style=\"color:var(--blue);\">“We already have a website”</h4><p style=\"margin-top:5px;font-size:15.5px;\">Great — I'm not saying scrap it. Most sites capture the visit but do nothing after. The piece I'd add is the follow-up: missed-call text-back and reminders so the leads you already get turn into jobs.</p></div><div class=\"card\"><h4 style=\"color:var(--blue);\">“It's too expensive”</h4><p style=\"margin-top:5px;font-size:15.5px;\">One extra job a month usually covers it several times over — and the leads you're missing cost more than the system does. Want me to walk the math on your numbers on a quick call?</p></div><div class=\"card\"><h4 style=\"color:var(--blue);\">“I tried this before and it didn't work”</h4><p style=\"margin-top:5px;font-size:15.5px;\">Usually that's a DIY tool nobody maintained. I manage the whole thing and you own all your data — no lock-in. If it's not pulling its weight, you're free to walk. Worth a fresh look?</p></div><div class=\"card\"><h4 style=\"color:var(--blue);\">“I can do it myself”</h4><p style=\"margin-top:5px;font-size:15.5px;\">You could — the question is whether you want to spend evenings wrestling with tech instead of running jobs or being home. I do it once, do it right, and maintain it.</p></div><div class=\"card\"><h4 style=\"color:var(--blue);\">“I need to think about it”</h4><p style=\"margin-top:5px;font-size:15.5px;\">Makes sense. Want me to send a one-page summary you can look over? I'll check back next week — no pressure either way.</p></div><div class=\"card\"><h4 style=\"color:var(--blue);\">“I'm locked into a contract”</h4><p style=\"margin-top:5px;font-size:15.5px;\">No problem. When does it wrap up? I'll set a reminder to reach out before renewal so you can compare. Meanwhile I'll send a short demo so it's on your radar.</p></div><div class=\"card\"><h4 style=\"color:var(--blue);\">“It's my slow season, let's talk later”</h4><p style=\"margin-top:5px;font-size:15.5px;\">Slow season is the best time to set this up — get it dialed in before the rush so you capture every lead when it counts. I build now, it's ready when you are.</p></div>\n<div class=\"tint\"><div class=\"eyebrow\">The universal move</div><p class=\"big\">Agree → reframe → re-ask, smaller. Validate the concern, flip it into a reason your system helps, then lower the next ask. Calm beats pushy every time.</p></div>\n</section><section id=\"metrics\">\n      <div class=\"kick\"><span class=\"num\">Section 12</span>&nbsp;Measurement</div>\n      <h2>Metrics & CRM tracking</h2><p class=\"sub\">The numbers that predict revenue</p>\n<div class=\"drow\"><div class=\"top\"><span class=\"nm\">Videos sent</span><span class=\"badge\">10 / day · 50 / wk</span></div><p>The one input you fully control — protect it</p></div><div class=\"drow\"><div class=\"top\"><span class=\"nm\">Open / watch rate</span><span class=\"badge\">50%+ watched</span></div><p>Subject line + hook quality. Low? Fix your opener</p></div><div class=\"drow\"><div class=\"top\"><span class=\"nm\">Reply rate</span><span class=\"badge\">10–20%</span></div><p>Relevance & personalization. Low? Your leak isn't compelling</p></div><div class=\"drow\"><div class=\"top\"><span class=\"nm\">Calls booked</span><span class=\"badge\">3–5 / wk</span></div><p>Whether your CTA and follow-up are working</p></div><div class=\"drow\"><div class=\"top\"><span class=\"nm\">Proposals sent</span><span class=\"badge\">2–4 / wk</span></div><p>Call quality and fit of the prospects you chose</p></div><div class=\"drow\"><div class=\"top\"><span class=\"nm\">Clients closed</span><span class=\"badge\">1–2 / wk</span></div><p>The number that pays the bills</p></div>\n<div class=\"soft\"><div class=\"eyebrow\">Minimum viable tracker</div><p>A sheet or CRM with: <b>Business · Contact · Channel · Leak flagged · Date sent · Watched? · Replied? · Next follow-up · Stage.</b> Enough to run the whole sequence without dropping anyone.</p></div>\n<div class=\"tip\"><div class=\"lbl\">Pro tip</div><p>Review the funnel every Friday in 10 minutes. Find the <b>biggest single drop-off</b> and fix only that next week.</p></div>\n<div class=\"card\"><div class=\"eyebrow\">Eat your own cooking</div><p>Run your own outreach on the same backbone (Cal.com, automated reminders, owned data). Living inside the system makes the demo effortless and the pitch honest.</p></div>\n</section><section id=\"casestudy\">\n      <div class=\"kick\"><span class=\"num\">Section 13</span>&nbsp;Proof</div>\n      <h2>The case study template</h2><p class=\"sub\">Turn wins into proof</p>\n<div class=\"card\"><div class=\"eyebrow\">Fill-in-the-blank structure</div>\n<div style=\"margin-top:4px;\">\n<h4 class=\"mini\" style=\"margin-top:6px;\">1 · The client</h4><p style=\"font-size:15px;\">[Trade] in [city]. One line on size and what they do.</p>\n<h4 class=\"mini\">2 · The problem</h4><p style=\"font-size:15px;\">The leak you found. \"Missing ~__ calls/week with no capture.\"</p>\n<h4 class=\"mini\">3 · What I set up</h4><p style=\"font-size:15px;\">The system in plain English — site, text-back, follow-up.</p>\n<h4 class=\"mini\">4 · The result</h4><p style=\"font-size:15px;\">A concrete number: \"+__ booked jobs/mo,\" \"__% more quotes.\"</p>\n<h4 class=\"mini\">5 · Their words</h4><p style=\"font-size:15px;\">A short quote from the owner. Real, specific, unpolished.</p>\n<h4 class=\"mini\">6 · The takeaway</h4><p style=\"font-size:15px;margin:0;\">One line another contractor would see themselves in.</p></div></div>\n<div class=\"tint\"><div class=\"eyebrow\">Worked example</div><p><b>Harbor HVAC, San Luis Obispo.</b> A two-tech shop missing ~a dozen calls a week with no after-hours capture. I launched a mobile-first site with instant missed-call text-back and automatic follow-up. Within six weeks they were booking <b>8–10 extra jobs a month</b> from leads that used to vanish. <em>\"I had no idea how many calls I was losing until they stopped getting lost.\"</em></p></div>\n<div class=\"tip\"><div class=\"lbl\">Where to use it</div><p>Day-21 follow-up, the \"I tried this before\" objection, your website, and as the second video to a warm-but-quiet prospect. Proof from a business that looks like theirs beats any feature list.</p></div>\n</section><section id=\"plan\">\n      <div class=\"kick\"><span class=\"num\">Section 14</span>&nbsp;The plan</div>\n      <h2>The 90-day outreach plan</h2><p class=\"sub\">Daily goals across three phases</p>\n<div class=\"phase\"><div class=\"ph\"><span class=\"lab\">Phase 1</span></div><h4>Days 1–30 · Build the habit</h4><p class=\"g\">Make recording effortless and the daily rhythm automatic. Quality of reps over quantity.</p><ul style=\"margin:0;\"><li><b>5 videos/day</b>, ramping to 10 by week 4</li><li>Lock the recording block at the same time daily</li><li>Build tomorrow's list every afternoon</li><li>Set up Loom, Cal.com, and your tracker</li><li><b>Target:</b> 1–2 calls booked by day 30</li></ul></div><div class=\"phase\"><div class=\"ph\"><span class=\"lab\">Phase 2</span></div><h4>Days 31–60 · Build the volume</h4><p class=\"g\">Hit a steady 10/day and let follow-up volume start producing calls.</p><ul style=\"margin:0;\"><li><b>10 videos/day</b>, 50/week, no missed days</li><li>Full 30-day sequences on autopilot</li><li>Friday funnel review — fix one leak/week</li><li>First case study captured</li><li><b>Target:</b> 3–4 calls/wk, first closes</li></ul></div><div class=\"phase\"><div class=\"ph\"><span class=\"lab\">Phase 3</span></div><h4>Days 61–90 · Build the conversion</h4><p class=\"g\">Keep volume steady while tightening watch → reply → call → close.</p><ul style=\"margin:0;\"><li>Hold <b>10/day</b> — the habit runs itself</li><li>Double down on the trades + scripts that convert</li><li>2–3 case studies feeding follow-ups</li><li>Ask every happy client for a referral</li><li><b>Target:</b> 1–2 closes/week, predictable pipeline</li></ul></div>\n<h3 class=\"blk\">Weekly targets <span style=\"font-size:14px;font-weight:400;color:var(--muted);\">(P1 · P2 · P3)</span></h3>\n<div class=\"drow\"><div class=\"top\"><span class=\"nm\">Videos / week</span></div><p style=\"color:var(--ink);font-size:15px;\">25→50 · 50 · 50</p></div><div class=\"drow\"><div class=\"top\"><span class=\"nm\">Replies / week</span></div><p style=\"color:var(--ink);font-size:15px;\">3–6 · 6–10 · 8–12</p></div><div class=\"drow\"><div class=\"top\"><span class=\"nm\">Calls booked</span></div><p style=\"color:var(--ink);font-size:15px;\">1–2/mo · 3–4/wk · 4–6/wk</p></div><div class=\"drow\"><div class=\"top\"><span class=\"nm\">Clients closed</span></div><p style=\"color:var(--ink);font-size:15px;\">0–1/mo · 1–2/mo · 1–2/wk</p></div>\n<div class=\"tint\"><div class=\"eyebrow\">After 90 days</div><p>You'll have sent <b>600+ personalized videos</b>, built a follow-up engine that works while you sleep, and have real proof and a repeatable rhythm. Outreach stops being a campaign and becomes how the business runs.</p></div>\n</section><section id=\"checklist\">\n      <div class=\"kick\"><span class=\"num\">Section 15</span>&nbsp;Daily ops</div>\n      <h2>The daily checklist</h2><p class=\"sub\">Print it. Run it. Every day.</p>\n<div class=\"chkbar\"><button id=\"chk-reset\" type=\"button\">↻ Reset day</button></div>\n<div class=\"grouplbl\">Prep & record</div>\n<div class=\"chk\"><div class=\"box\"></div><div class=\"tx\">Pull yesterday's pre-scored prospect list</div></div>\n<div class=\"chk\"><div class=\"box\"></div><div class=\"tx\">Open each site + Google profile; note <b>one leak</b> each</div></div>\n<div class=\"chk\"><div class=\"box\"></div><div class=\"tx\">Loom set to Screen + Cam, correct mic, clean browser</div></div>\n<div class=\"chk\"><div class=\"box\"></div><div class=\"tx\">Record <b>10 videos</b> — one take each, no rewatching</div></div>\n<div class=\"chk\"><div class=\"box\"></div><div class=\"tx\">Title each: “Quick idea for [Business] 👋”</div></div>\n<div class=\"grouplbl\">Send & log</div>\n<div class=\"chk\"><div class=\"box\"></div><div class=\"tx\">Deliver each via best channel (email / DM / SMS)</div></div>\n<div class=\"chk\"><div class=\"box\"></div><div class=\"tx\">Log every send in the tracker with leak + date</div></div>\n<div class=\"chk\"><div class=\"box\"></div><div class=\"tx\">Add CTA / Cal.com link where the channel allows</div></div>\n<div class=\"grouplbl\">Follow up & reply</div>\n<div class=\"chk\"><div class=\"box\"></div><div class=\"tx\">Work the queue: day 3, 7, 14, 21, 30 touches</div></div>\n<div class=\"chk\"><div class=\"box\"></div><div class=\"tx\">Prioritize <b>watchers</b> who haven't replied yet</div></div>\n<div class=\"chk\"><div class=\"box\"></div><div class=\"tx\">Reply to every inbound within the hour</div></div>\n<div class=\"chk\"><div class=\"box\"></div><div class=\"tx\">Send booking link / confirm any call times</div></div>\n<div class=\"grouplbl\">Close out the day</div>\n<div class=\"chk\"><div class=\"box\"></div><div class=\"tx\">Build tomorrow's list of 10–15 scored prospects</div></div>\n<div class=\"chk\"><div class=\"box\"></div><div class=\"tx\">Update stages for anyone who moved forward</div></div>\n<div class=\"chk\"><div class=\"box\"></div><div class=\"tx\">Friday only: 10-min funnel review, pick 1 fix</div></div>\n<div class=\"tip\" style=\"margin-top:16px;\"><div class=\"lbl\">Daily minimum</div><p>10 sent · queue cleared · tomorrow's list built. Hit those three and the day counts — everything else is upside.</p></div>\n</section><section id=\"pricing\">\n      <div class=\"kick\"><span class=\"num\">Section 16</span>&nbsp;The offer</div>\n      <h2>Offer & pricing reference</h2><p class=\"sub\">The numbers to quote with confidence — one offer, one price</p>\n<div class=\"tint\" style=\"text-align:center;\">\n  <div class=\"eyebrow\" style=\"margin-bottom:6px;\">Done-for-You Intake System</div>\n  <div style=\"font-family:'Inter';font-weight:700;font-size:26px;color:var(--blue);line-height:1.06;\">$1,500 <span style=\"font-size:14px;font-weight:600;color:var(--muted);\">setup</span> + $297<span style=\"font-size:14px;font-weight:600;color:var(--muted);\">/mo</span></div>\n  <div style=\"margin-top:9px;\"><span class=\"badge navy\">No lock-in</span> <span class=\"badge navy\">30-day guarantee</span></div>\n</div>\n<div class=\"card\"><h4>Done-for-You Intake System — $1,500 + $297/mo</h4><p>Missed-call text-back, instant replies, online booking, automatic follow-up, and lead logging &mdash; fully managed. Works with their current website, or includes a new one. Same price either way.</p></div>\n<div class=\"card\"><h4>Fallback only: Starter Site — $950 one-time</h4><p>A website only: mobile-first, their own domain, contact form, online booking, live in 5&ndash;7 days. No text-back. Bring it up only when they have no site and no interest in text-back yet, when the EIN or business-line requirement blocks them, or when price is the blocker and the $97 audit isn't the right step. It upgrades into the Intake System later without a rebuild.</p></div>\n<p class=\"sub\" style=\"margin:-4px 0 16px;\">Lead with the Intake System every time — it's the only offer on the site. The sales script covers when to fall back to the Starter Site.</p>\n<div class=\"soft\"><div class=\"eyebrow\">What's included</div>\n<ul style=\"margin:0;\"><li>Missed-call text-back from their business line, with two-way texting</li><li>An instant reply to every website quote request</li><li>Online booking that drops estimates on their calendar</li><li>Automatic follow-up, with them stepping in when a lead replies</li><li>Lead logging, carrier registration, monitoring, edits &amp; all software costs</li></ul></div>\n<div class=\"soft\"><div class=\"eyebrow\">How to say it</div>\n<ul style=\"margin:0;\"><li>Say the real number on the call — $1,500 to set up, $297/mo, no written-quote guessing game</li><li>No hourly billing, no surprise invoices</li><li>Cancel anytime, and a 30-day guarantee: if it isn't answering and following up on their leads in the first month, they cancel and keep the website and domain</li></ul></div>\n<div class=\"tip\"><div class=\"lbl\">Anchor for \"it's too expensive\"</div><p>Don't defend the price — reframe to outcomes. At $297/mo, <b>one extra booked job a month usually covers it several times over</b>, and the leads they're missing today cost more than the system does. If it's still a stretch, the $97 intake audit is the proof step; the Starter Site only fits if what they really need is just a website.</p></div>\n</section>\n</div>\n<div class=\"foot\">\n  <p class=\"big\">Find the contractor with a visible leak. Show it to them in 60 seconds. Hand them the fix. Follow up until it's a yes.</p>\n  <div class=\"sm\">Alignment Automations · Internal Sales Playbook · v1.0</div>\n  <a class=\"totop\" href=\"#contents\">↑ Back to contents</a>\n</div>";
